// int(str) with CPython's decimal-literal grammar.

import { isDecimalDigit, decimalDigitValue, isIntWhitespace } from '../unicode/properties.mjs';

// Accepts surrounding whitespace, one optional sign, a run of Unicode Nd
// digits, and underscores only *between* digits. Returns a BigInt, or null
// when the text is not a valid literal — int() has no size limit, so neither
// does this.
export function pyInt(text) {
  const chars = Array.from(text);
  let start = 0;
  let end = chars.length;
  while (start < end && isIntWhitespace(chars[start])) start += 1;
  while (end > start && isIntWhitespace(chars[end - 1])) end -= 1;

  let negative = false;
  if (start < end && (chars[start] === '+' || chars[start] === '-')) {
    negative = chars[start] === '-';
    start += 1;
  }

  let digits = '';
  let afterDigit = false;
  for (let index = start; index < end; index += 1) {
    const ch = chars[index];
    if (ch === '_') {
      // A separator is only legal once a digit has been seen, and never twice
      // in a row — which also rejects a leading underscore.
      if (!afterDigit) return null;
      afterDigit = false;
      continue;
    }
    if (!isDecimalDigit(ch)) return null;
    digits += String(decimalDigitValue(ch));
    afterDigit = true;
  }
  // False here means no digits at all, or a trailing underscore.
  if (!afterDigit) return null;

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}
// str.encode(...) for the one codec this program needs.

import { PyBytes } from './bytes.mjs';
import { UnicodeEncodeError } from './errors.mjs';

// The strict ascii codec. Positions are counted in code points, matching
// CPython, so an astral character occupies one position rather than two.
export function encodeAscii(text) {
  const codes = [];
  let position = 0;
  for (const ch of text) {
    const codePoint = ch.codePointAt(0);
    if (codePoint > 0x7f) throw new UnicodeEncodeError('ascii', codePoint, position);
    codes.push(codePoint);
    position += 1;
  }
  return new PyBytes(codes);
}
// Unicode predicates behind Python's str semantics.
//
// Node's RegExp Unicode property escapes expose the same category data
// CPython consults, so no tables need to be tabulated by hand here.

const NON_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;
const DECIMAL_DIGIT = /^\p{Nd}$/u;
const SPACE_SEPARATOR = /^\p{Zs}$/u;

// The blanks int() strips from around a literal: the ASCII whitespace run,
// NEL, and the line/paragraph separators. Together with the Zs category below
// this is str.isspace() minus U+001C..U+001F, which int() rejects even though
// isspace() accepts them.
const INT_BLANKS = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20, 0x85, 0x2028, 0x2029,
]);

// str.isprintable(): everything outside the C* and Z* categories, plus the
// space character itself, which is printable despite being Zs.
export function isPrintable(ch) {
  return ch === ' ' || !NON_PRINTABLE.test(ch);
}

export function isIntWhitespace(ch) {
  return INT_BLANKS.has(ch.codePointAt(0)) || SPACE_SEPARATOR.test(ch);
}

export function isDecimalDigit(ch) {
  return DECIMAL_DIGIT.test(ch);
}

// Start of the maximal run of consecutive Nd code points containing `codePoint`,
// memoised because a run can be walked repeatedly while scanning one literal.
const runStarts = new Map();

function decimalRunStart(codePoint) {
  const cached = runStarts.get(codePoint);
  if (cached !== undefined) return cached;
  let start = codePoint;
  while (start > 0 && DECIMAL_DIGIT.test(String.fromCodePoint(start - 1))) start -= 1;
  runStarts.set(codePoint, start);
  return start;
}

// Each Nd block is ten consecutive code points running 0..9, and a run of
// digits is always a whole number of such blocks laid end to end — most runs
// hold one block, but the mathematical digits at U+1D7CE..U+1D7FF pack five
// adjacent blocks into a single fifty-code-point run. Taking the offset from
// the run's start modulo ten therefore gives the value in every case, whereas
// stopping at the first non-digit below would read the later blocks as zeros.
export function decimalDigitValue(ch) {
  const codePoint = ch.codePointAt(0);
  return (codePoint - decimalRunStart(codePoint)) % 10;
}

// Python's repr() for the value shapes this program prints.

import { PyBytes } from './bytes.mjs';
import { isPrintable } from '../unicode/properties.mjs';

// repr prefers single quotes, switching to double only when that avoids
// escaping — i.e. when the value contains ' but no ".
function pickQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? '"' : "'";
}

// The only mnemonic escapes repr emits. Notably \v, \f, \a and \b are *not*
// among them; those fall through to \xHH.
const MNEMONIC_ESCAPES = new Map([
  [0x5c, '\\\\'],
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

function hexEscape(codePoint) {
  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

export function reprBytes(value) {
  const { codes } = value;
  const quote = pickQuote(codes.includes(0x27), codes.includes(0x22));
  const quoteCode = quote.charCodeAt(0);
  let out = `b${quote}`;
  for (const code of codes) {
    const mnemonic = MNEMONIC_ESCAPES.get(code);
    if (mnemonic !== undefined) out += mnemonic;
    else if (code === quoteCode) out += `\\${quote}`;
    else if (code < 0x20 || code >= 0x7f) out += hexEscape(code);
    else out += String.fromCharCode(code);
  }
  return out + quote;
}

export function reprStr(text) {
  const quote = pickQuote(text.includes("'"), text.includes('"'));
  let out = quote;
  for (const ch of text) {
    const codePoint = ch.codePointAt(0);
    const mnemonic = MNEMONIC_ESCAPES.get(codePoint);
    if (mnemonic !== undefined) out += mnemonic;
    else if (ch === quote) out += `\\${quote}`;
    else if (!isPrintable(ch)) out += hexEscape(codePoint);
    else out += ch;
  }
  return out + quote;
}

export function reprInt(value) {
  return String(value);
}

// Containers delegate to repr for their members, exactly as Python does.
export function pyRepr(value) {
  if (value instanceof PyBytes) return reprBytes(value);
  if (typeof value === 'bigint') return reprInt(value);
  if (typeof value === 'string') return reprStr(value);
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof Map) {
    const entries = [];
    for (const [key, item] of value) entries.push(`${pyRepr(key)}: ${pyRepr(item)}`);
    return `{${entries.join(', ')}}`;
  }
  if (value === null) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  return String(value);
}
// The `type=` callables the source script passes to add_argument.
//
// Each exposes the __name__ argparse quotes in "invalid <name> value: ..." and
// a convert() returning null to signal a conversion failure.

import { pyInt } from '../python/numbers.mjs';

export const STR = {
  name: 'str',
  // str(x) on a command-line token is the identity, and never fails.
  convert(text) {
    return text;
  },
};

export const INT = {
  name: 'int',
  convert(text) {
    return pyInt(text);
  },
};

