// Throwaway generator for the "randomised-sweep" fuzz dimension.
// Deterministic LCG (no Math.random). Writes batch files to /tmp/rsw-NN.json.

import { writeFileSync } from 'node:fs';

// ---- LCG -----------------------------------------------------------------
let state = 0x13572468;
function next() {
  state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
  return state;
}
function rnd() {
  return next() / 4294967296;
}
function ri(n) {
  return Math.floor(rnd() * n) % n;
}
function pick(arr) {
  return arr[ri(arr.length)];
}
function wpick(table) {
  let total = 0;
  for (const [w] of table) total += w;
  let r = rnd() * total;
  for (const [w, v] of table) {
    r -= w;
    if (r < 0) return v;
  }
  return table[table.length - 1][1];
}

// ---- code point sources --------------------------------------------------
// NUL excluded everywhere: it cannot survive execve() and would just be
// skipped by the harness.
function cpAscii() {
  return 1 + ri(0x7f); // 0x01..0x7f
}
function cpLatin1() {
  return 1 + ri(0xff); // 0x01..0xff
}
function cpBmp() {
  for (;;) {
    const cp = 1 + ri(0xffff);
    if (cp >= 0xd800 && cp <= 0xdfff && rnd() < 0.85) continue; // mostly avoid
    return cp;
  }
}
function cpAstral() {
  return 0x10000 + ri(0x100000);
}
function cpMixed() {
  return wpick([[45, cpAscii], [20, cpLatin1], [25, cpBmp], [10, cpAstral]])();
}

const CP_SOURCES = [cpAscii, cpLatin1, cpBmp, cpAstral, cpMixed];

function randLen() {
  return wpick([
    [6, () => 0],
    [30, () => 1 + ri(4)],
    [30, () => 1 + ri(24)],
    [18, () => 1 + ri(200)],
    [10, () => 1 + ri(1200)],
    [6, () => 1 + ri(4001)],
  ])();
}

function randString(source) {
  const n = randLen();
  let out = '';
  for (let i = 0; i < n; i += 1) out += String.fromCodePoint(source());
  return out;
}

const A_SPECIALS = [
  '', ' ', '  ', '\t', '\n', '\r', '\r\n', '\x7f', '\x1b', "'", '"', '\'"',
  '\\', 'a\\b', '--b', '-', '--', '-5', '--a', '=', 'a=b', '--a=x',
  '\x01\x02\x03', 'x'.repeat(4000), '\x7f'.repeat(300), ' '.repeat(64),
  'ÿ', '', ' ', ' ', ' ', '', '﻿',
  '😀', '\u{10ffff}', 'café', '中文',
];

function randA() {
  return wpick([[8, () => pick(A_SPECIALS)], [92, () => randString(pick(CP_SOURCES))]])();
}

// ---- --b sources ---------------------------------------------------------
const DIGITS = '0123456789';
function randDigits(n) {
  let s = '';
  for (let i = 0; i < n; i += 1) s += DIGITS[ri(10)];
  return s;
}

function bWellFormedInt() {
  const nDigits = wpick([
    [25, () => 1],
    [25, () => 1 + ri(9)],
    [15, () => 1 + ri(19)],
    [12, () => 10 + ri(30)],
    [12, () => 40 + ri(160)],
    [11, () => 100 + ri(500)], // hundreds of digits
  ])();
  let s = randDigits(nDigits);
  if (rnd() < 0.15) s = '0'.repeat(1 + ri(5)) + s;
  const sign = wpick([[60, ''], [25, '-'], [15, '+']]);
  const ws = ['', ' ', '  ', '\t', '\n', '\r', '\x0b', '\x0c', ' ',
    ' ', ' ', '　', ' ', ' ', ' ', ''];
  const lead = rnd() < 0.3 ? pick(ws) : '';
  const trail = rnd() < 0.3 ? pick(ws) : '';
  if (rnd() < 0.18 && s.length > 2) {
    const at = 1 + ri(s.length - 1);
    s = s.slice(0, at) + '_' + s.slice(at);
  }
  return lead + sign + s + trail;
}

const B_MALFORMED_SEEDS = [
  '', ' ', '-', '+', '--', '+-', '-+', '_', '_1', '1_', '1__2', '0x10',
  '0b1', '0o7', '1e3', '1.0', '.5', '5.', 'inf', 'Inf', 'infinity', 'nan',
  'NaN', 'None', 'True', 'null', '1 2', '1,2', '1 000', '٣.', '12abc',
  'abc', ' ', '​1', '1​', ' 1', '1 ', '¹1',
  '﻿1', '1﻿', '- 1', '+ 1', '1-', '1+', '(1)', '[1]', '½',
  '³', '¼', 'Ⅻ', '〇', '一', '零', '− 1',
  '−5', '＋5', '－5', '1', '1', '1', '1 ',
];

function bMalformed() {
  return wpick([
    [40, () => pick(B_MALFORMED_SEEDS)],
    [30, () => {
      const s = randDigits(1 + ri(20));
      const junk = pick(['a', 'Z', '.', ',', ' ', '-', '+', '_', 'e', 'x',
        '²', '๐', '‎', '/', ':', '⁄', ' ', '️']);
      const at = ri(s.length + 1);
      return s.slice(0, at) + junk + s.slice(at);
    }],
    [15, () => randString(pick(CP_SOURCES))],
    [15, () => {
      let s = '';
      const n = 1 + ri(4);
      for (let i = 0; i < n; i += 1) s += pick(['-', '+']);
      return s + randDigits(ri(6));
    }],
  ])();
}

// Start of each Unicode Nd 0..9 run, spread across the whole repertoire.
const ND_BLOCK_STARTS = [
  0x0030, 0x0660, 0x06f0, 0x07c0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66,
  0x0be6, 0x0c66, 0x0ce6, 0x0d66, 0x0de6, 0x0e50, 0x0ed0, 0x0f20, 0x1040,
  0x1090, 0x17e0, 0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0,
  0x1c40, 0x1c50, 0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0,
  0xff10, 0x104a0, 0x10d30, 0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0,
  0x11450, 0x114d0, 0x11650, 0x116c0, 0x11730, 0x118e0, 0x11c50, 0x11d50,
  0x16a60, 0x16b50, 0x1d7ce, 0x1d7d8, 0x1d7e2, 0x1d7ec, 0x1d7f6, 0x1e950,
];

function bUnicodeDigits() {
  const n = 1 + ri(14);
  const mode = ri(3);
  let base = pick(ND_BLOCK_STARTS);
  let s = '';
  for (let i = 0; i < n; i += 1) {
    if (mode === 1) base = pick(ND_BLOCK_STARTS);
    s += String.fromCodePoint(base + ri(10));
  }
  if (mode === 2) {
    const sign = pick(['', '-', '+']);
    const ws = pick(['', ' ', '\t', '　', ' ']);
    s = ws + sign + s + ws;
    if (rnd() < 0.3 && s.length > 2) {
      const at = 1 + ri(s.length - 1);
      s = s.slice(0, at) + '_' + s.slice(at);
    }
  }
  return s;
}

function randB() {
  return wpick([[50, bWellFormedInt], [28, bMalformed], [22, bUnicodeDigits]])();
}

// ---- argv shaping -------------------------------------------------------
function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i -= 1) {
    const j = ri(i + 1);
    const t = a[i]; a[i] = a[j]; a[j] = t;
  }
  return a;
}

function shapeArgv(a, b) {
  const shape = wpick([
    [56, 'normal'],
    [6, 'swapped'],
    [6, 'equals'],
    [4, 'dashForms'],
    [5, 'dupA'],
    [5, 'dupB'],
    [4, 'omitA'],
    [4, 'omitB'],
    [3, 'omitBoth'],
    [4, 'shuffled'],
    [3, 'extraPositional'],
  ]);
  const A = ['--a', a];
  const B = ['--b', b];
  switch (shape) {
    case 'normal': return [...A, ...B];
    case 'swapped': return [...B, ...A];
    case 'equals': {
      const ea = rnd() < 0.5 ? [`--a=${a}`] : A;
      const eb = rnd() < 0.5 ? [`--b=${b}`] : B;
      return [...ea, ...eb];
    }
    case 'dashForms': {
      const av = pick([['-a', a], ['--a', a], ['-a' + a], ['--a' + a]]);
      const bv = pick([['-b', b], ['--b', b], ['-b' + b], ['--b' + b]]);
      return [...(Array.isArray(av) ? av : [av]), ...(Array.isArray(bv) ? bv : [bv])];
    }
    case 'dupA': return [...A, ...B, '--a', randA()];
    case 'dupB': return [...A, ...B, '--b', randB()];
    case 'omitA': return [...B];
    case 'omitB': return [...A];
    case 'omitBoth': return rnd() < 0.5 ? [] : [pick(['--a', '--b'])];
    case 'shuffled': return shuffle([...A, ...B]);
    case 'extraPositional': {
      const out = [...A, ...B];
      const at = ri(out.length + 1);
      out.splice(at, 0, pick(['x', '', '-', '--', '5', a.slice(0, 8) || 'q']));
      return out;
    }
    default: return [...A, ...B];
  }
}

// ---- emit ---------------------------------------------------------------
const TOTAL = Number(process.argv[2] ?? 3600);
const BATCHES = Number(process.argv[3] ?? 24);
const PREFIX = process.argv[4] ?? '/tmp/rsw';

const cases = [];
for (let i = 0; i < TOTAL; i += 1) {
  cases.push({ name: `r${i}`, argv: shapeArgv(randA(), randB()) });
}

const per = Math.ceil(TOTAL / BATCHES);
let written = 0;
for (let bi = 0; bi < BATCHES; bi += 1) {
  const slice = cases.slice(bi * per, (bi + 1) * per);
  if (slice.length === 0) continue;
  writeFileSync(`${PREFIX}-${String(bi).padStart(2, '0')}.json`, JSON.stringify(slice));
  written += slice.length;
}

let nulTokens = 0;
let maxLen = 0;
let emptyArgv = 0;
for (const c of cases) {
  if (c.argv.length === 0) emptyArgv += 1;
  for (const t of c.argv) {
    if (t.includes('�')) nulTokens += 1;
    if (t.length > maxLen) maxLen = t.length;
  }
}
console.log(`wrote ${written} cases, ${BATCHES} batches, prefix ${PREFIX}`);
console.log(`NUL tokens: ${nulTokens}, longest token: ${maxLen}, empty argv: ${emptyArgv}`);

